function makeLoot(type){
 const pools={barrel:[['wood',8,22],['stone',8,22],['metalOre',4,12],['sulfurOre',4,12],['cloth',3,9],['components',2,6],['scrap',3,8]],crate:[['wood',12,28],['stone',12,28],['metalOre',6,16],['sulfurOre',6,16],['cloth',4,12],['components',3,8],['scrap',5,12],['metal',3,8]],military:[['components',7,15],['scrap',10,20],['metal',8,18],['ammo',8,20],['pistolAmmo',8,20],['gunpowder',5,14],['sulfur',5,14],['cloth',6,15]],supply:[['components',15,25],['scrap',20,35],['metal',15,30],['ammo',15,30],['pistolAmmo',15,30],['gunpowder',10,22],['sulfur',10,22]]};
 let pool=(pools[type]||pools.crate).slice(),out={},count=type==='barrel'?2:type==='crate'?3:4;
 for(let i=0;i<count;i++){let j=Math.floor(Math.random()*pool.length),[key,min,max]=pool.splice(j,1)[0];out[key]=(min+Math.floor(Math.random()*(max-min+1)))*multiplier}
 if(type==='military'&&Math.random()<.22)out.signal=1;
 if(type==='supply'){out[Math.random()<.5?'rifle':'smg']=1;if(Math.random()<.45)out.c4=1}
 return out;
}
const LOOT_DESPAWN_MS=3000, LOOT_RESPAWN_MS=300000;
function scheduleEmptyLoot(o,now=performance.now()){
 if(!o||!['crate','military','supply'].includes(o.type)||o.hp<=0)return;
 let empty=!Object.values(o.contents||{}).some(n=>n>0);
 if(empty&&o.despawnAt==null)o.despawnAt=now+LOOT_DESPAWN_MS;
 else if(!empty)o.despawnAt=null;
}
function tickLootTimers(now=performance.now()){
 for(const o of objects){
  if(o.despawnAt!=null&&now>=o.despawnAt){
   if(lootTarget===o)closeLoot();
   o.hp=0;o.brokenVisible=false;o.respawnAt=o.despawnAt+LOOT_RESPAWN_MS;o.despawnAt=null;cacheKey='';
  }
  if(o.respawnAt!=null&&now>=o.respawnAt){
   o.hp=o.type==='barrel'?2:o.type==='supply'?1:4;o.respawnAt=null;o.despawnAt=null;o.brokenVisible=false;delete o.contents;cacheKey='';
  }
 }
}
