function paintMap(){let c=$('islandMap'),g=c.getContext('2d'),size=c.width,unit=size/(2*MAP_HALF),toX=x=>(x+MAP_HALF)*unit,toY=z=>(MAP_HALF-z)*unit;g.fillStyle='#527f80';g.fillRect(0,0,size,size);g.beginPath();for(let i=0;i<=72;i++){let a=i*Math.PI*2/72,r=COAST_RADIUS+Math.sin(a*3)*8+Math.cos(a*5)*4,x=toX(Math.cos(a)*r),y=toY(Math.sin(a)*r);i?g.lineTo(x,y):g.moveTo(x,y)}g.closePath();g.fillStyle='#c8bd93';g.fill();g.save();g.translate(size/2,size/2);g.scale(.90,.90);g.translate(-size/2,-size/2);g.fillStyle='#728d64';g.fill();g.restore();g.strokeStyle='#ffffff25';g.lineWidth=1;for(let n=0;n<=6;n++){let t=n*size/6;g.beginPath();g.moveTo(t,0);g.lineTo(t,size);g.moveTo(0,t);g.lineTo(size,t);g.stroke()}function dot(x,z,color,r){g.fillStyle=color;g.beginPath();g.arc(toX(x),toY(z),r,0,7);g.fill()}for(let o of objects){if(o.hp<=0)continue;if(['crate','military','supply'].includes(o.type))dot(o.x,o.z,o.type==='crate'?'#eadfb6':'#e9a46e',o.type==='crate'?3:5);if(o.type==='drop')dot(o.x,o.z,'#d7bf87',2)}for(let o of built)if(['foundation','wall','doorframe','ceiling','cupboard'].includes(o.type)){g.fillStyle='#f5e4c3';g.fillRect(toX(o.x)-2,toY(o.z)-2,5,5)}g.beginPath();g.arc(toX(FISHING.x),toY(FISHING.z),FISHING.r*unit,0,7);g.fillStyle='#7bc88a55';g.fill();g.strokeStyle='#c1efd0';g.lineWidth=2;g.stroke();for(let [x,z,label] of [[15,10,'ЗАПРАВКА'],[-43,20,'СУПЕРМАРКЕТ'],[FISHING.x,FISHING.z,'РЫБАЦКИЙ ПОСЁЛОК'],...EXPEDITION_SITES.map(q=>[q.x,q.z,q.name])]){dot(x,z,'#de8a69',7);g.fillStyle='#26382b';g.font='bold 16px Arial';g.textAlign=x>85?'right':'left';g.fillText(label,toX(x)+(x>85?-10:10),toY(z)-8)}g.save();g.translate(toX(player.x),toY(player.z));g.rotate(player.yaw);g.fillStyle='#faf7e9';g.strokeStyle='#253b30';g.lineWidth=3;g.beginPath();g.moveTo(0,-12);g.lineTo(8,9);g.lineTo(0,5);g.lineTo(-8,9);g.closePath();g.fill();g.stroke();g.restore()}
