 box(59,.04,82,3.3,.23,15,plank);for(let i=0;i<23;i++)box(59,.27,75+i*.61,3.25,.045,.028,['#665340']);for(let z of [76,80,84,88])for(let x of [57.3,60.7]){box(x,.02,z,.19,1.15,.19,timber);box(x,1.05,z,.24,.08,.24,plank)}
