 box(x,.02,z+9,17,.25,3,iron);box(x+10,0,z+8,.4,8,.4,iron);box(x+6,7.8,z+8,8.4,.3,.3,iron);box(x+3,5.1,z+8,.08,2.7,.08,iron);
