let joy=$('joystick'),stick=$('stick');function joyMove(e){let b=joy.getBoundingClientRect(),x=(e.clientX-(b.left+b.width/2))/(b.width/joy.clientWidth||1),y=(e.clientY-(b.top+b.height/2))/(b.height/joy.clientHeight||1),d=Math.hypot(x,y),max=joy.clientWidth*.32;if(d>max){x=x/d*max;y=y/d*max}touchMove={x:x/max,y:y/max};stick.style.transform=`translate(${x}px,${y}px)`}joy.addEventListener('pointerdown',e=>{joy.setPointerCapture(e.pointerId);joyMove(e)});joy.addEventListener('pointermove',e=>{if(joy.hasPointerCapture(e.pointerId))joyMove(e)});function joyEnd(){touchMove={x:0,y:0};stick.style.transform=''}joy.addEventListener('pointerup',joyEnd);joy.addEventListener('pointercancel',joyEnd);let looking=null;canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&mode==='game'){looking={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)}});canvas.addEventListener('pointermove',e=>{if(looking&&e.pointerId===looking.id){player.yaw+=(e.clientX-looking.x)*.006;player.pitch=Math.max(-1.1,Math.min(1.1,player.pitch-(e.clientY-looking.y)*.006));looking.x=e.clientX;looking.y=e.clientY}});canvas.addEventListener('pointerup',()=>looking=null);canvas.addEventListener('pointercancel',()=>looking=null);
